pm.test("Health endpoint returns 200 OK", function () {
    pm.response.to.have.status(200);
});

pm.test("Health endpoint returns the correct response", function () {
    pm.expect(pm.response.json()).to.eql({ ok: true });
});

pm.test("Users endpoint returns 200 OK", function () {
    pm.response.to.have.status(200);
});

pm.test("Users response is a JSON array", function () {
    pm.expect(pm.response.json()).to.be.an("array");
});

pm.test("Each user contains the required fields", function () {
    const users = pm.response.json();

    users.forEach(function (user) {
        pm.expect(user).to.have.property("id");
        pm.expect(user).to.have.property("username");
        pm.expect(user).to.have.property("email");
    });
});

pm.test("API documentation returns 200 OK", function () {
    pm.response.to.have.status(200);
});

pm.test("API documentation is returned as JSON", function () {
    pm.expect(pm.response.headers.get("Content-Type")).to.include("application/json");
});

pm.test("API documentation contains OpenAPI information", function () {
    const response = pm.response.json();
    pm.expect(response).to.have.property("openapi");
    pm.expect(response).to.have.property("paths");
});

pm.test("Invalid endpoint returns 404 Not Found", function () {
    pm.response.to.have.status(404);
});

pm.test("Invalid endpoint returns a JSON error response", function () {
    pm.expect(pm.response.json()).to.have.property("detail");
});
